def choose_move(observation):
    # Defensive access to observation fields
    my_pos = observation.get('player_position', [0, 0])
    grid_size = observation.get('grid_size', [10, 10])
    resource_positions = observation.get('resources', [])
    opponents = observation.get('opponents', [])
    territory_targets = observation.get('territory_targets', [])
    mode = observation.get('mode', 'resource_collection')  # resource_collection, pursuit_evasion, territory_control

    # Initialize move to stay in place
    dx, dy = 0, 0

    # Helper functions
    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    # Determine moves based on mode
    if mode == 'resource_collection':
        if resource_positions:
            # Find nearest resource
            nearest = min(resource_positions, key=lambda r: dist(my_pos, r))
            dx = 0
            dy = 0
            delta_x = nearest[0] - my_pos[0]
            delta_y = nearest[1] - my_pos[1]
            if abs(delta_x) > abs(delta_y):
                dx = 1 if delta_x > 0 else -1
            elif delta_y != 0:
                dy = 1 if delta_y > 0 else -1
            else:
                dx = 0
                dy = 0
        else:
            dx, dy = 0, 0

    elif mode == 'pursuit_evasion':
        if opponents:
            # Pursue the nearest opponent
            target = min(opponents, key=lambda o: dist(my_pos, o))
            delta_x = target[0] - my_pos[0]
            delta_y = target[1] - my_pos[1]
            if abs(delta_x) > abs(delta_y):
                dx = 1 if delta_x > 0 else -1
            elif delta_y != 0:
                dy = 1 if delta_y > 0 else -1
            else:
                dx, dy = 0, 0
        else:
            dx, dy = 0, 0

    elif mode == 'territory_control':
        if territory_targets:
            # Move towards the nearest target area
            target = min(territory_targets, key=lambda t: dist(my_pos, t))
            delta_x = target[0] - my_pos[0]
            delta_y = target[1] - my_pos[1]
            if abs(delta_x) > abs(delta_y):
                dx = 1 if delta_x > 0 else -1
            elif delta_y != 0:
                dy = 1 if delta_y > 0 else -1
            else:
                dx, dy = 0, 0
        else:
            dx, dy = 0, 0
    else:
        # Default: no movement
        dx, dy = 0, 0

    # Clamp the move to -1, 0, 1 (defensive)
    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))
    return [dx, dy]

